	modify profile [name]
	  options:
	    alert-client-side-caching [enabled | disabled]
	    alert-identifier [string]
	    alert-path [string]
	    alert-pool [[name] | none]
	    alert-publisher [[name] | none]
	    alert-token-header [string]
	    app-layer-encryption {
	      fail-open [enabled | disabled]
	    }
